package com.pousadamarealta;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.*;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;

import java.io.IOException;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

@Testcontainers
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ReservationSystemIT {

    @Container
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:18")
        .withDatabaseName("pousada")
        .withUsername("test")
        .withPassword("test");

    private static Process serverProcess;
    private static final int SERVER_PORT = 17070;

    @BeforeAll
    static void setUp() throws Exception {
        System.setProperty("DB_URL", postgres.getJdbcUrl());
        System.setProperty("DB_USER", postgres.getUsername());
        System.setProperty("DB_PASSWORD", postgres.getPassword());
        System.setProperty("PORT", String.valueOf(SERVER_PORT));

        ProcessBuilder pb = new ProcessBuilder(
            "java",
            "-DDB_URL=" + postgres.getJdbcUrl(),
            "-DDB_USER=" + postgres.getUsername(),
            "-DDB_PASSWORD=" + postgres.getPassword(),
            "-DPORT=" + SERVER_PORT,
            "-cp",
            System.getProperty("java.class.path"),
            "com.pousadamarealta.App"
        );
        pb.inheritIO();
        serverProcess = pb.start();

        Thread.sleep(3000);

        RestAssured.baseURI = "http://localhost";
        RestAssured.port = SERVER_PORT;
    }

    @AfterAll
    static void tearDown() {
        if (serverProcess != null) {
            serverProcess.destroy();
        }
    }

    @Test
    @Order(1)
    void shouldListRooms() {
        given()
            .when()
            .get("/rooms")
            .then()
            .statusCode(200)
            .body("size()", is(5))
            .body("[0].number", is("101"))
            .body("[0].type", is("STANDARD"))
            .body("[0].capacity", is(2))
            .body("[0].nightlyRate", is(249.90f));
    }

    @Test
    @Order(2)
    void shouldCreateReservation() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "101");
        request.put("guestName", "Ana Silva");
        request.put("guestEmail", "ana@gmail.com");
        request.put("guestCpf", "12345678900");
        request.put("checkIn", "2027-03-10");
        request.put("checkOut", "2027-03-12");
        request.put("guests", 2);
        request.put("ratePlan", "STANDARD");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", notNullValue())
            .body("status", is("PENDING"))
            .body("nights", is(2))
            .body("subtotal", is(499.80f))
            .body("discount", is(0.00f))
            .body("total", is(499.80f))
            .body("amountPaid", is(0.00f));
    }

    @Test
    @Order(3)
    void shouldCalculateHighSeasonPricing() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "101");
        request.put("guestName", "Carlos Dias");
        request.put("guestEmail", "carlos@example.com");
        request.put("guestCpf", "11122233344");
        request.put("checkIn", "2027-07-10");
        request.put("checkOut", "2027-07-12");
        request.put("guests", 2);
        request.put("ratePlan", "STANDARD");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("subtotal", is(599.76f));
    }

    @Test
    @Order(4)
    void shouldApplyNonRefundableDiscount() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "201");
        request.put("guestName", "Maria Costa");
        request.put("guestEmail", "maria@example.com");
        request.put("guestCpf", "55566677788");
        request.put("checkIn", "2027-03-10");
        request.put("checkOut", "2027-03-12");
        request.put("guests", 2);
        request.put("ratePlan", "NON_REFUNDABLE");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("subtotal", is(779.80f))
            .body("discount", is(116.97f))
            .body("total", is(662.83f));
    }

    @Test
    @Order(5)
    void shouldRejectInvalidEmail() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "102");
        request.put("guestName", "João Santos");
        request.put("guestEmail", "joao.gmail.com");
        request.put("guestCpf", "99988877766");
        request.put("checkIn", "2027-04-01");
        request.put("checkOut", "2027-04-03");
        request.put("guests", 1);
        request.put("ratePlan", "STANDARD");

        int reservationId = given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .when()
            .post("/reservations/" + reservationId + "/confirmation")
            .then()
            .statusCode(200);

        List<Map<String, Object>> messages = given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .extract()
            .jsonPath()
            .getList("$");

        boolean hasBlocked = messages.stream()
            .anyMatch(m -> "BLOCKED".equals(m.get("status")));

        Assertions.assertTrue(hasBlocked, "Should have blocked message for invalid email");
    }

    @Test
    @Order(6)
    void shouldPreventDoubleBooking() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "101");
        request.put("guestName", "Pedro Lima");
        request.put("guestEmail", "pedro@example.com");
        request.put("guestCpf", "11111111111");
        request.put("checkIn", "2027-03-10");
        request.put("checkOut", "2027-03-12");
        request.put("guests", 1);
        request.put("ratePlan", "STANDARD");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(409)
            .body("error", is("ROOM_UNAVAILABLE"));
    }

    @Test
    @Order(7)
    void shouldRejectExceedingCapacity() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "102");
        request.put("guestName", "Grupo Grande");
        request.put("guestEmail", "grupo@example.com");
        request.put("guestCpf", "22222222222");
        request.put("checkIn", "2027-05-01");
        request.put("checkOut", "2027-05-02");
        request.put("guests", 5);
        request.put("ratePlan", "STANDARD");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(422)
            .body("error", is("CAPACITY_EXCEEDED"));
    }

    @Test
    @Order(8)
    void shouldGenerateOccupancyReport() {
        String csv = given()
            .queryParam("date", "2027-03-10")
            .when()
            .get("/reports/occupancy")
            .then()
            .statusCode(200)
            .contentType(containsString("text/csv"))
            .extract()
            .asString();

        Assertions.assertTrue(csv.contains("room,type,reservation,check_in,check_out"));
        Assertions.assertTrue(csv.contains("total,1/5"));
    }

    @Test
    @Order(9)
    void shouldGenerateRevenueReport() {
        String csv = given()
            .queryParam("month", "2027-03")
            .when()
            .get("/reports/revenue")
            .then()
            .statusCode(200)
            .contentType(containsString("text/csv"))
            .extract()
            .asString();

        Assertions.assertTrue(csv.contains("reservation,room,check_in,check_out,status,amount"));
        Assertions.assertTrue(csv.contains("total,"));
    }

    @Test
    @Order(10)
    void shouldCompleteReservationLifecycle() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", "301");
        request.put("guestName", "Família Souza");
        request.put("guestEmail", "familia@example.com");
        request.put("guestCpf", "33333333333");
        request.put("checkIn", "2027-06-15");
        request.put("checkOut", "2027-06-17");
        request.put("guests", 4);
        request.put("ratePlan", "STANDARD");

        int id = given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .extract()
            .path("id");

        given()
            .when()
            .post("/reservations/" + id + "/confirmation")
            .then()
            .statusCode(200)
            .body("status", is("CONFIRMED"));

        given()
            .when()
            .post("/reservations/" + id + "/check-in")
            .then()
            .statusCode(200)
            .body("status", is("CHECKED_IN"));

        given()
            .when()
            .post("/reservations/" + id + "/check-out")
            .then()
            .statusCode(200)
            .body("title", is("Comprovante de reserva"))
            .body("reservationId", is(id));

        given()
            .when()
            .get("/reservations/" + id + "/document")
            .then()
            .statusCode(200)
            .body("title", is("Comprovante de reserva"));
    }
}

